"""Measure certificate margins: how close f==D and G+lambda>=0 are to failing."""
import sys, random, time
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/tests')
from te.engine.worker import solve_worker
from stress_worker import gen_problem, tol


def margins(owned, paths, caps, demand, mode, rho, B, prop):
    E = len(caps)
    x = {}
    for i, k in enumerate(owned):
        for p, v in enumerate(prop["flow"][i]):
            x[(k, p)] = float(v)
    L = [0.0] * E
    for k in owned:
        for p, path in enumerate(paths[k]):
            v = x[(k, p)]
            if v:
                for e in path:
                    L[e] += v
    G = {}
    for k in owned:
        if demand[k] <= 0:
            continue
        for p, path in enumerate(paths[k]):
            if path is None or not all(caps[e] > 0 for e in path):
                continue
            g = x[(k, p)]
            for e in path:
                g += rho * (L[e] / caps[e] - B[e]) / caps[e]
            if mode == "admit":
                g -= 1.0
            G[(k, p)] = g
    f = 0.5 * sum(v * v for v in x.values())
    for e in range(E):
        if caps[e] > 0:
            f += 0.5 * rho * (L[e] / caps[e] - B[e]) ** 2
    if mode == "admit":
        f -= sum(x.values())
    D = f
    for (k, p), g in G.items():
        D -= x[(k, p)] * g
    for i, k in enumerate(owned):
        D -= demand[k] * prop["potential"][i]
    fd = abs(f - D) / tol(f, D)
    worst_sign = 0.0
    for i, k in enumerate(owned):
        for (kk, p), g in G.items():
            if kk != k:
                continue
            val = g + prop["potential"][i]
            worst_sign = min(worst_sign, val / tol(val, 0.0))
    return fd, worst_sign


def main(seed0, N, big):
    from stress_worker import BIG
    import stress_worker
    stress_worker.BIG = big
    rng = random.Random(seed0)
    worst_fd = 0.0
    worst_sign = 0.0
    t0 = time.time()
    for i in range(N):
        owned, paths, caps, demand, mode, rho, B = gen_problem(rng)
        prop = solve_worker(owned, paths, caps, demand, mode, rho, B)
        if prop["status"] != "optimal":
            continue
        fd, sg = margins(owned, paths, caps, demand, mode, rho, B, prop)
        worst_fd = max(worst_fd, fd)
        worst_sign = min(worst_sign, sg)
    print("N=%d big=%s worst |f-D|/tol=%.3g worst (G+lam)/tol=%.3g time %.1fs"
          % (N, big, worst_fd, worst_sign, time.time() - t0))


if __name__ == "__main__":
    main(int(sys.argv[1]), int(sys.argv[2]), len(sys.argv) > 3 and sys.argv[3] == "big")
